<?php
// No Composer or Node.js required. PHP 8 + PDO MySQL.
class ApiError extends Exception { public int $http; public function __construct($message,$http=400){parent::__construct($message);$this->http=$http;} }
function fail($message,$code=400){throw new ApiError($message,$code);}
function send($data,$code=200){http_response_code($code);echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
function uid($prefix=''){return $prefix.bin2hex(random_bytes(16));}
function db(){global $config;static $pdo;if(!$pdo){$pdo=new PDO('mysql:host='.$config['db_host'].';dbname='.$config['db_name'].';charset=utf8mb4',$config['db_user'],$config['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_STRINGIFY_FETCHES=>false]);$pdo->exec("SET time_zone = '+00:00'");}return $pdo;}
function query($sql,$params=[]){$s=db()->prepare($sql);$s->execute($params);return $s;}
function rows($sql,$params=[]){return query($sql,$params)->fetchAll();}
function one($sql,$params=[]){return query($sql,$params)->fetch()?:null;}
function transaction($fn){$pdo=db();$pdo->beginTransaction();try{$v=$fn();$pdo->commit();return $v;}catch(Throwable $e){$pdo->rollBack();throw $e;}}
function insertRow($table,$data){$cols=array_keys($data);query('INSERT INTO '.$table.' (`'.implode('`,`',$cols).'`) VALUES ('.implode(',',array_fill(0,count($cols),'?')).')',array_values($data));}
function updateRow($table,$id,$data){if(!$data)return;query('UPDATE '.$table.' SET '.implode(',',array_map(fn($k)=>'`'.$k.'`=?',array_keys($data))).' WHERE id=?',[...array_values($data),$id]);}
function need($body,$keys){foreach($keys as $k){if(!isset($body[$k])||$body[$k]==='')fail('Required field: '.$k);}}
function settings(){return one('SELECT * FROM system_settings LIMIT 1')??fail('Import the database SQL first.',503);}
function thresholds(){ $s=settings();return ['critical'=>(float)$s['critical_threshold'],'warning'=>(float)$s['warning_threshold']];}
function pct($a,$n){return $n<=0?100.0:round(max(0,$a)*100/$n,2);}
function category($p){$t=thresholds();return $p<$t['critical']?'CRITICAL':($p<$t['warning']?'WARNING':'SAFE');}
function userProfile($id){$u=one('SELECT u.*,d.name department_name FROM users u LEFT JOIN departments d ON d.id=u.department_id WHERE u.id=?',[$id]);if(!$u)fail('User not found.',401);unset($u['password_hash']);$s=one('SELECT id FROM students WHERE is_active=1 AND (email=? OR (roll_no=? AND division_id IN (SELECT id FROM class_divisions WHERE department_id=?))) LIMIT 1',[$u['email'],$u['employee_id'],$u['department_id']]);$u['student_id']=$u['role']==='STUDENT'?($s['id']??null):null;return $u;}
function b64url($v){return rtrim(strtr(base64_encode($v),'+/','-_'),'=');}
function issueToken($u){global $config;$p=b64url(json_encode(['id'=>$u['id'],'exp'=>time()+7*86400]));return $p.'.'.b64url(hash_hmac('sha256',$p,$config['auth_secret'],true));}
function auth(){global $config,$user;if($user)return $user;$h=$_SERVER['HTTP_AUTHORIZATION']??$_SERVER['REDIRECT_HTTP_AUTHORIZATION']??'';if(!preg_match('/^Bearer ([A-Za-z0-9_.-]+)$/',$h,$m))fail('Please sign in.',401);$parts=explode('.',$m[1]);if(count($parts)!==2||!hash_equals(b64url(hash_hmac('sha256',$parts[0],$config['auth_secret'],true)),$parts[1]))fail('Invalid session. Please sign in again.',401);$p=json_decode(base64_decode(strtr($parts[0],'-_','+/')),true);if(!is_array($p)||($p['exp']??0)<time()||empty($p['id']))fail('Session expired. Please sign in again.',401);return $user=userProfile($p['id']);}
function role($roles=['ADMIN','FACULTY','HOD']){$u=auth();if(!in_array($u['role'],(array)$roles,true))fail('Your account cannot perform this action.',403);return $u;}
function student($id){return one("SELECT s.*,CONCAT(cd.year_level,' ',cd.division) division_name,CONCAT(cd.year_level,' ',cd.division) class_name,cd.year_level,cd.division,cd.department_id,d.name department_name,d.code department_code FROM students s JOIN class_divisions cd ON s.division_id=cd.id JOIN departments d ON cd.department_id=d.id WHERE s.id=? OR s.roll_no=? LIMIT 1",[$id,$id])??fail('Student not found.',404);}
function ownStudent($s){$u=auth();divisionAccess($s['division_id']);if($u['role']==='STUDENT'&&($u['student_id']===null||$u['student_id']!==$s['id']))fail('You can only view your own attendance.',403);}
function editable($created){$u=role();$s=settings();if($u['role']!=='ADMIN'&&time()-strtotime($created.' UTC')>(int)$s['edit_window_hours']*3600)fail('Attendance edit window has expired. Ask an Admin to edit this record.',403);}
function filterSql(&$sql,&$params,$filters,$values){foreach($filters as $key=>$column){if(isset($values[$key])&&$values[$key]!==''&&$values[$key]!=='ALL'){$sql.=' AND '.$column.'=?';$params[]=$values[$key];}}}
function studentRows($q=[]){$sql="SELECT s.*,CONCAT(cd.year_level,' ',cd.division) division_name,cd.year_level,cd.division,cd.department_id,d.name department_name FROM students s JOIN class_divisions cd ON cd.id=s.division_id JOIN departments d ON d.id=cd.department_id WHERE 1=1";$p=[];scopeSql($sql,$p,'cd.department_id');$active=$q['active_status']??'ACTIVE';if($active!=='ALL'){$sql.=' AND s.is_active=?';$p[]=$active==='INACTIVE'?0:1;}filterSql($sql,$p,['division_id'=>'s.division_id','year'=>'cd.year_level','division'=>'cd.division'],$q);if(!empty($q['class_name'])){$sql.=" AND (cd.year_level=? OR CONCAT(cd.year_level,' ',cd.division)=? OR CONCAT(cd.year_level,' E&TC')=?)";$p=[...$p,$q['class_name'],$q['class_name'],$q['class_name']];}if(!empty($q['search'])){$sql.=' AND (s.full_name LIKE ? OR s.roll_no LIKE ? OR s.prn LIKE ?)';$x='%'.$q['search'].'%';$p=[...$p,$x,$x,$x];}return rows($sql.' ORDER BY s.roll_no',$p);}
function validSessions($q=[],$submitted=false){$sql="SELECT sess.*,sess.id session_id,sub.name subject_name,sub.code subject_code,u.full_name faculty_name FROM attendance_sessions sess JOIN subjects sub ON sub.id=sess.subject_id LEFT JOIN users u ON u.id=sess.faculty_user_id WHERE NOT EXISTS(SELECT 1 FROM holiday_calendar h WHERE h.event_date=sess.session_date AND h.is_instructional_day=0)";$p=[];scopeSql($sql,$p,'(SELECT department_id FROM class_divisions WHERE id=sess.division_id)');filterSql($sql,$p,['division_id'=>'sess.division_id','subject_id'=>'sess.subject_id'],$q);if($submitted)$sql.=" AND sess.status='SUBMITTED'";foreach(['start_date'=>'>=','end_date'=>'<='] as $key=>$op){if(!empty($q[$key])){$sql.=' AND sess.session_date'.$op.'?';$p[]=$q[$key];}}return rows($sql.' ORDER BY sess.session_date,sess.lecture_slot',$p);}
function statsFor($s,$sessions){$sessions=array_values(array_filter($sessions,fn($x)=>$x['division_id']===$s['division_id']));$ids=array_column($sessions,'id');$valid=array_flip($ids);$records=rows('SELECT ar.*,sess.subject_id FROM attendance_records ar JOIN attendance_sessions sess ON sess.id=ar.session_id WHERE ar.student_id=?',[$s['id']]);$present=0;$subs=[];foreach($sessions as $v){$k=$v['subject_id'];if(!isset($subs[$k]))$subs[$k]=['subject_id'=>$k,'subject_name'=>$v['subject_name'],'subject_code'=>$v['subject_code'],'conducted'=>0,'attended'=>0];$subs[$k]['conducted']++;}foreach($records as $r){if(isset($valid[$r['session_id']])&&in_array($r['status'],['PRESENT','LATE'])){$present++;$subs[$r['subject_id']]['attended']++;}}foreach($subs as &$v){$v['percentage']=pct($v['attended'],$v['conducted']);$v['category']=category($v['percentage']);}unset($v);$p=pct($present,count($sessions));return ['total_conducted'=>count($sessions),'total_attended'=>$present,'attendance_percentage'=>$p,'status_category'=>category($p),'subject_breakdown'=>array_values($subs)];}
function logBio($action,$studentId,$details){$u=auth();insertRow('biometric_audit_logs',['id'=>uid(),'action'=>$action,'student_id'=>$studentId,'user_id'=>$u['id'],'details'=>$details,'ip_address'=>$_SERVER['REMOTE_ADDR']??null]);}
function photoBytes($data){$s=settings();if(!is_string($data)||strlen($data)>(float)$s['max_image_size_mb']*1024*1024*1.4)fail('Photo exceeds the configured size limit.');if(!preg_match('#^data:image/(png|jpeg|jpg|webp);base64,(.+)$#s',$data,$m))fail('Upload a JPEG, PNG or WebP photo.');$bytes=base64_decode($m[2],true);if($bytes===false||strlen($bytes)>(float)$s['max_image_size_mb']*1024*1024)fail('Invalid or oversized image.');$info=@getimagesizefromstring($bytes);if(!$info||!in_array($info['mime'],['image/png','image/jpeg','image/webp']))fail('Invalid image content.');if($info[0]*$info[1]>40000000)fail('Image resolution is too large. Resize it below 40 megapixels.');return [$bytes,['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$info['mime']]];}
function savePhoto($data){[$bytes,$ext]=photoBytes($data);$dir=dirname(__DIR__).'/uploads/students';if(!is_dir($dir)&&!mkdir($dir,0755,true))fail('Cannot create photo directory.',500);$file=uid('student_').'.'.$ext;if(file_put_contents($dir.'/'.$file,$bytes)===false)fail('Cannot save photo.',500);return '/uploads/students/'.$file;}
function engine($payload){global $config;$url=$config['face_service_url']??'';$key=$config['face_service_key']??'';if(!$url||!$key)fail('Face recognition service is not connected. Set face_service_url and face_service_key in api/config.php. Manual attendance is available.',503);if(!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https')fail('Face service must use HTTPS.',503);if(!function_exists('curl_init'))fail('PHP cURL is required for the face service.',503);$c=curl_init($url);curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_HTTPHEADER=>['Content-Type: application/json','X-Service-Key: '.$key],CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>45,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_FOLLOWLOCATION=>false]);$text=curl_exec($c);$status=curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);$r=is_string($text)?json_decode($text,true):null;if($status!==200||!is_array($r))fail('Face service is unavailable. Check its HTTPS URL, service key and server logs.',503);return $r;}

// Every access decision uses the current database account, never the token's role.
function staffScoped(){return in_array(auth()['role'],['FACULTY','HOD'],true);}
function departmentAccess($department){$u=auth();if(staffScoped()&&(!$u['department_id']||$u['department_id']!==$department))fail('Access is limited to your assigned department.',403);}
function scopeSql(&$sql,&$params,$column){$u=auth();if(staffScoped()){if(!$u['department_id'])fail('Ask Admin to assign your department.',403);$sql.=' AND '.$column.'=?';$params[]=$u['department_id'];}}
function divisionAccess($id){$d=one('SELECT * FROM class_divisions WHERE id=?',[$id])??fail('Division not found.',404);departmentAccess($d['department_id']);$u=auth();if($u['role']==='STUDENT'){$st=one('SELECT division_id FROM students WHERE id=?',[$u['student_id']]);if(!$st||$st['division_id']!==$id)fail('Access is limited to your class.',403);}return $d;}
function collegeEmail($email){global $config;$domains=$config['allowed_email_domains']??['zcoer.in'];$domain=strtolower(substr(strrchr($email,'@')?:'',1));if(!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($domain,array_map('strtolower',$domains),true))fail('Use an approved Zeal college email address.');}
function boundedText($value,$label,$max=4000){if(!is_string($value)||trim($value)===''||strlen($value)>$max)fail($label.' is required and must be within '.$max.' characters.');return trim($value);}
function preflightScope($path,$q,$body){
 $u=auth();if(staffScoped()&&!$u['department_id'])fail('Ask Admin to assign your department.',403);
 foreach([$q,$body] as $data){if(!empty($data['division_id'])&&$data['division_id']!=='ALL')divisionAccess($data['division_id']);if(!empty($data['subject_id'])&&$data['subject_id']!=='ALL'){$sub=one('SELECT division_id FROM subjects WHERE id=?',[$data['subject_id']])??fail('Subject not found.',404);divisionAccess($sub['division_id']);}if(!empty($data['student_id']))ownStudent(student($data['student_id']));}
 if(preg_match('#^/students/([^/]+)(?:/attendance-profile)?$#',$path,$m)&&!in_array($m[1],['attendance-list','audit-logs','bulk-import']))ownStudent(student(urldecode($m[1])));
 if(preg_match('#^/attendance/session/([^/]+)$#',$path,$m)){$v=one('SELECT division_id FROM attendance_sessions WHERE id=?',[$m[1]])??fail('Session not found.',404);divisionAccess($v['division_id']);}
 if(preg_match('#^/attendance/(?:record|student-record)/([^/]+)$#',$path,$m)){$v=one('SELECT sess.division_id FROM attendance_records ar JOIN attendance_sessions sess ON sess.id=ar.session_id WHERE ar.id=?',[$m[1]])??fail('Record not found.',404);divisionAccess($v['division_id']);}
}

function validateDate($d){if(!is_string($d)||!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$d,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))fail('Date must be a valid YYYY-MM-DD date.');}
